(() => new Promise((resolve, reject) => {
  // 라이브 run 은 실제 데이터를 남긴다 — **새 1:1 대화**를 열어 가장 값싼 질문 하나만 보낸다.
  //  (공유방에 보내면 AI ask 가 아니라 그룹 채팅 메시지로 나가고, 남의 방을 건드린다 —
  //   선행 시도에서 실측한 함정. 여기서는 참여자가 나뿐인 새 대화만 쓴다.)
  const t0 = Date.now();
  const tick = () => {
    const p = document.getElementById('promptInput');
    const msgs = document.querySelectorAll('article.message').length;
    const ro = [...document.querySelectorAll('.composer-hint, .composer-readonly, [class*=readonly]')]
      .map((e) => (e.textContent || '').trim()).join(' ');
    if (p && !p.disabled && !p.readOnly && msgs === 0) {
      if (/읽기 전용/.test(ro)) return reject(new Error('PB0008 FAIL: 읽기 전용 대화'));
      return resolve(JSON.stringify({ ready: true, msgs, href: location.href }));
    }
    if (Date.now() - t0 > 20000) return reject(new Error('PB0008 FAIL: 빈 새 대화 진입 실패 (msgs=' + msgs + ')'));
    setTimeout(tick, 500);
  };
  tick();
}))()

(() => new Promise((resolve, reject) => {
  // 라이브 패널을 연 뒤 **재오픈 없이** 폴링 재렌더만으로 새 단계에 시각 표기가 붙는지 본다.
  //  (openStepSidePanel(pending) → state.stepSidePanelLive=true → refreshStepSidePanel 이 갱신)
  const btn = document.querySelector('.pending-bubble-view-btn');
  if (!btn) return reject(new Error('PB0008 FAIL: 라이브 단계 보기 버튼 없음'));
  btn.click();
  const read = () => [...document.querySelectorAll('.step-side-panel-time')].map((t) => t.textContent.trim());
  const first = read();
  if (!first.length) return reject(new Error('PB0008 FAIL: 라이브 패널에 시각 표기 0'));
  const CLOCK = /^\d{2}:\d{2}:\d{2}$/;
  const FULL = /^\d{2}:\d{2}:\d{2} · \+(?:\d+(?:\.\d)?초|\d+분 \d+초) · 누적 (?:\d+(?:\.\d)?초|\d+분 \d+초)$/;
  const secs = (s) => {
    const m = /누적 (?:(\d+)분 )?(\d+(?:\.\d)?)초$/.exec(s);
    return m ? (parseInt(m[1] || '0', 10) * 60 + parseFloat(m[2])) : NaN;
  };
  const t0 = Date.now();
  const tick = () => {
    const now = read();
    if (now.length > first.length) {
      const added = now.slice(first.length);
      const badFmt = added.filter((s) => !FULL.test(s));
      const cum = now.filter((s) => FULL.test(s)).map(secs);
      const monotonic = cum.every((v, i) => i === 0 || v >= cum[i - 1]);
      const bad = [];
      if (!CLOCK.test(now[0])) bad.push('firstNotClockOnly=' + now[0]);
      if (badFmt.length) bad.push('addedBadFmt=' + JSON.stringify(badFmt));
      if (!monotonic) bad.push('누적 비단조=' + JSON.stringify(cum));
      // 재오픈 없이 갱신됐는지 — 패널이 계속 열려 있는 상태여야 한다.
      if (document.getElementById('stepSidePanel').classList.contains('hidden')) bad.push('panelClosed');
      if (bad.length) return reject(new Error('PB0008 ASSERT FAIL LIVE ' + JSON.stringify(bad)));
      return resolve(JSON.stringify({
        before: first.length, after: now.length, elapsedMs: Date.now() - t0,
        addedSample: added.slice(0, 3), firstLabel: now[0], lastLabel: now[now.length - 1],
        cumMonotonic: monotonic,
      }));
    }
    if (Date.now() - t0 > 150000) {
      return reject(new Error('PB0008 FAIL: 150초 내 폴링으로 새 단계가 추가되지 않음 (before=' + first.length + ')'));
    }
    setTimeout(tick, 1000);
  };
  setTimeout(tick, 1000);
}))()

(() => {
  // 라이브 패널을 그대로 복제해 2.2× 확대 — 진행 중 화면의 시각 표기를 판독 가능하게 남긴다.
  document.querySelectorAll('#pb-steptiming-zoom').forEach((n) => n.remove());
  const panel = document.getElementById('stepSidePanel');
  const host = document.createElement('div');
  host.id = 'pb-steptiming-zoom';
  host.setAttribute('data-marker', 'steptiming-live-pb0008-ef1f438a');
  host.style.cssText = 'position:fixed;inset:0;z-index:2147483647;background:#fff;overflow:auto';
  const hd = document.createElement('div');
  hd.style.cssText = 'font:600 13px/1.5 system-ui;padding:10px 20px;border-bottom:1px solid #e5e9f0;color:#26251e';
  hd.textContent = 'PB-0008 · 라이브 run 진행 중 패널(폴링 재렌더) 2.2× 확대 · marker=steptiming-live-pb0008-ef1f438a';
  host.appendChild(hd);
  const stage = document.createElement('div');
  stage.style.cssText = 'transform:scale(2.2);transform-origin:top left;width:' + Math.round(panel.getBoundingClientRect().width) + 'px';
  const clone = panel.cloneNode(true);
  clone.removeAttribute('id');
  clone.style.cssText = 'position:static;width:100%;height:auto;max-height:none;box-shadow:none;border:1px solid #e5e9f0';
  const body = clone.querySelector('#stepSidePanelBody');
  if (body) { body.style.maxHeight = 'none'; body.style.overflow = 'visible'; }
  stage.appendChild(clone);
  host.appendChild(stage);
  document.body.appendChild(host);
  const n = host.querySelectorAll('.step-side-panel-time').length;
  if (!n) throw new Error('PB0008 FAIL: 라이브 확대 복제에 시간 표기 0');
  return JSON.stringify({ zoomedTimes: n });
})()
